import{_ as e,o as a,c as l,a6 as r}from"./chunks/framework.B_q3ZJNF.js";const p=JSON.parse('{"title":"差异清单：本课程的简化与真实世界","description":"","frontmatter":{"title":"差异清单：本课程的简化与真实世界"},"headers":[],"relativePath":"vision-rag-course/divergence.md","filePath":"vision-rag-course/docs/divergence.md"}'),o={name:"vision-rag-course/divergence.md"};function t(n,i,s,d,c,h){return a(),l("div",null,[...i[0]||(i[0]=[r('<h1 id="差异清单-本课程的简化与真实世界" tabindex="-1">差异清单：本课程的简化与真实世界 <a class="header-anchor" href="#差异清单-本课程的简化与真实世界" aria-label="Permalink to &quot;差异清单：本课程的简化与真实世界&quot;">​</a></h1><p>正文每一处「本课程简化为……」都集中登记在这里，按章排列。差异不是缺陷——每一项都是为了让原理可验证而做的诚实裁剪；想接真实世界时，照着这张表逐项换回即可。</p><h2 id="第-1-章-two-phase-funnel" tabindex="-1">第 1 章 two-phase-funnel <a class="header-anchor" href="#第-1-章-two-phase-funnel" aria-label="Permalink to &quot;第 1 章 two-phase-funnel&quot;">​</a></h2><ul><li>成本演算口径「一页页图 ≈ 1500 token」是本书声明的简化模型，非任何平台真实价格（正文已当场声明）。</li></ul><h2 id="第-2-章-vision-client" tabindex="-1">第 2 章 vision-client <a class="header-anchor" href="#第-2-章-vision-client" aria-label="Permalink to &quot;第 2 章 vision-client&quot;">​</a></h2><ul><li>data URL 的 MIME 用 text/plain：实验场的「图」是文本画（字符位图），真实平台传 image/jpeg 等图片字节。</li><li>指数退避为纯正翻倍（2→4→8→16s），无随机抖动、无上限封顶；生产实现两者都建议加。</li><li>密钥仅支持环境变量读取；真实工具常加「本地文件首行」的第二来源（同样不写进代码）。</li><li>重试循环对异常宽捕并加 <code># noqa: BLE001</code>（ruff 全局配置启用 BLE001）——教学取舍：重试语义优先于异常分类教学。</li></ul><h2 id="第-3-章-page-rendering" tabindex="-1">第 3 章 page-rendering <a class="header-anchor" href="#第-3-章-page-rendering" aria-label="Permalink to &quot;第 3 章 page-rendering&quot;">​</a></h2><ul><li>字符位图 Bitmap 代替真实 PNG 渲染产物（等宽字符网格）。</li><li>approx_tokens 是声明的简化计费模型（750 像素/token、向上取整），非平台真实价格。</li><li>合成页为 50×30 袖珍页、以 110 DPI 形态存储；绝对成本不代表真实 A4 页，仅保留平方比例律。</li><li>DPI 旋钮无长边像素封顶（真实工具常设单边上限）。</li><li>is_scanned 只检「无文字层」：空白页同样过检。</li></ul><h2 id="第-5-章-local-tfidf" tabindex="-1">第 5 章 local-tfidf <a class="header-anchor" href="#第-5-章-local-tfidf" aria-label="Permalink to &quot;第 5 章 local-tfidf&quot;">​</a></h2><ul><li>二字滑窗分词代替真实词级分词器（后者依赖词典）。</li><li>手工 29 词停用词表代替真实系统的数百词表。</li><li>min(tf, 8) 硬封顶代替真实引擎的平滑饱和函数（BM25 一类，正文仅方向性提及）。</li><li>词面 TF-IDF 代替真实世界常用的向量检索（词面盲区留给第 6 章视觉精排补）。</li><li>score_pages 不过滤「空白」页，由精排层把关。</li></ul><h2 id="第-6-章-vision-rerank" tabindex="-1">第 6 章 vision-rerank <a class="header-anchor" href="#第-6-章-vision-rerank" aria-label="Permalink to &quot;第 6 章 vision-rerank&quot;">​</a></h2><ul><li>精排成本账沿用第 3 章「750 像素/token」声明口径复算（一页 110 DPI 约 2 token），未引入真实平台价格；候选集一次打包进单次请求，未对齐真实平台的单请求图片数量/大小上限（超大候选集需分批，实验场候选固定在十来页）。</li><li>回退全程静默：不打印、不记日志；生产实现应留日志与指标（正文已当场声明）。</li></ul><h2 id="第-7-章-deep-read" tabindex="-1">第 7 章 deep-read <a class="header-anchor" href="#第-7-章-deep-read" aria-label="Permalink to &quot;第 7 章 deep-read&quot;">​</a></h2><ul><li>max_tokens=24576 为教学数值，非任何平台真实口径（「思考计入输出预算」仅方向性断言）。</li><li>拒答靠系统提示词约定＋管线原样透传；剧本验证的是「透传」这一管线侧承诺，不模拟模型真实拒答行为。</li><li>邻页半径固定 ±1（真实工程常按页型可配）。</li><li>文字层整页全文送入；真实长页需截断策略。</li><li>空命中页/语料外页码/texts 与 page_images 不等长抛 ValueError（契约未细规定，测试钉住）。</li></ul><h2 id="第-8-章-verifiable-delivery" tabindex="-1">第 8 章 verifiable-delivery <a class="header-anchor" href="#第-8-章-verifiable-delivery" aria-label="Permalink to &quot;第 8 章 verifiable-delivery&quot;">​</a></h2><ul><li>页图交付形态：真实工具导出/内嵌 PNG；实验场页图是字符网格，落盘为 page-N.txt、HTML 内以代码块文本内嵌（正文与 report.py docstring 均声明）。</li><li>真实自包含预览用 base64 data URL 内联 PNG；实验场直接文本内嵌，正文有对照说明。</li><li>预览文件名固定 preview.html（真实工具按文档名＋问题 slug 命名）。</li><li>亲手开机跑的是 ScriptedTransport 剧本引擎（零密钥零费用、确定性）；真 HTTP 引擎替换指向第 13 章。</li><li>cited_pages 只认形状不对账语料，对账缺口由交付层（export/preview 抛 ValueError）说破。</li></ul><h2 id="第-9-章-adaptive-sampling" tabindex="-1">第 9 章 adaptive-sampling <a class="header-anchor" href="#第-9-章-adaptive-sampling" aria-label="Permalink to &quot;第 9 章 adaptive-sampling&quot;">​</a></h2><ul><li>合成帧源（FrameSource）替代 mp4＋ffmpeg 真实抽帧；真相帧 2 Hz（真实视频 24~30 fps）。</li><li>突变分＝字符格点变化占比；真实工具为像素/压缩域 scene 分数。</li><li>auto_fps 四档分界为工程约定。</li><li>音频全程不进管线（「视觉模型没有耳朵」）；时间戳为采样估计（±半帧间隔）。</li><li>detect_scene_cuts 实现以格点突变分判定（不读 scene 标签）；合成素材上与标签变化重合。</li></ul><h2 id="第-10-章-frame-segments" tabindex="-1">第 10 章 frame-segments <a class="header-anchor" href="#第-10-章-frame-segments" aria-label="Permalink to &quot;第 10 章 frame-segments&quot;">​</a></h2><ul><li>段长 30 秒是工程约定；末段 end 为标称边界可越过片尾（第 11 章切片时收口）。</li><li>运动强度三档是模型主观分级而非物理量；合成素材的真相 motion 仅供测试当裁判。</li><li>帧级兜底卡为全空（视频帧没有文字层可退，与 PDF 侧不同）。</li><li>回执时刻贴合容差：多帧批＝半个批内最大间隔；单帧批无限。</li></ul><h2 id="第-11-章-video-qa" tabindex="-1">第 11 章 video-qa <a class="header-anchor" href="#第-11-章-video-qa" aria-label="Permalink to &quot;第 11 章 video-qa&quot;">​</a></h2><ul><li>parse_ts 只回收单个 [MM:SS] 时刻，不认 [MM:SS-MM:SS] 区间写法（真实工具会回收区间两端）。</li><li>fmt_ts 向下取整到秒、负数按 0 兜底；超一小时用 H:MM:SS。</li><li>切片范围只交付 (起点, 终点) 浮点对，不产真视频文件；真实切片仅方向性提及。</li><li>关键帧导出无独立公开 API，以「时刻→最近已抽帧」惯用法交付（平手取先到帧）。</li></ul><h2 id="第-12-章-micro-zoom" tabindex="-1">第 12 章 micro-zoom <a class="header-anchor" href="#第-12-章-micro-zoom" aria-label="Permalink to &quot;第 12 章 micro-zoom&quot;">​</a></h2><ul><li>真相帧 0.5 秒一张 → 12fps 重抽后贴最近真帧、去重后每 0.5 秒一帧（素材上限；真实视频 24-30fps 帧帧不同）。</li><li>「放大」＝中心裁切本身、不插值（真实工具裁后放大回原尺寸）。</li><li>触发为词表词面命中（会漏会多）；裁切尺寸 28×8 由合成素材构图决定（真实工具常用中心约四成）。</li><li>run_micro 罢工如实抛错；真实工具尽力而为、不毁主答案。</li><li>motion_peak_window 的 clamp 分两处：起点收口 0、终点由 extract_micro 对 source.duration 收口。</li></ul><h2 id="第-13-章-engine-porting" tabindex="-1">第 13 章 engine-porting <a class="header-anchor" href="#第-13-章-engine-porting" aria-label="Permalink to &quot;第 13 章 engine-porting&quot;">​</a></h2><ul><li>实验场只有一名假引擎（ScriptedTransport）；双引擎互验以原理示意与纪律给出、不上机。</li><li>真实引擎行为只做方向性断言（始终思考、无上传接口、按分辨率计费）；具体数值随版本变化、一律不写死。</li><li>ThinkingDialect 翻译演示是用法示例，不进实验场。</li></ul><h2 id="第-14-章-package-as-skill" tabindex="-1">第 14 章 package-as-skill <a class="header-anchor" href="#第-14-章-package-as-skill" aria-label="Permalink to &quot;第 14 章 package-as-skill&quot;">​</a></h2><ul><li>助手工具调度只做方向性断言（各家助手内部实现不同、决策输入是介绍文字），伪码标「原理示意」。</li><li>渐进披露的演算数字（常驻 20 份 × 2000/200 token）是假设口径，量级关系为真。</li><li>示范 SKILL.md 是自包含「用法示例」模板，companion 不新增 skill 文件。</li></ul>',28)])])}const m=e(o,[["render",t]]);export{p as __pageData,m as default};
